import os
from pathlib import Path

# ==========================================
# DIRECTORY CONFIGURATION
# ==========================================
# Base directories
INPUT_DIR = Path("./input")
METADATA_DIR = Path("./metadata")
WORKING_DIR = Path("./working/idea_3")
SUBMISSION_DIR = Path("./submission")

# Ensure output directories exist
WORKING_DIR.mkdir(parents=True, exist_ok=True)
SUBMISSION_DIR.mkdir(parents=True, exist_ok=True)

# ==========================================
# DATA PATHS
# ==========================================
# Metadata Parquet Files (Generated by metadata script)
TRAIN_DATA_PATH = METADATA_DIR / "train_metadata.parquet"
VAL_DATA_PATH = METADATA_DIR / "val_metadata.parquet"
TEST_DATA_PATH = METADATA_DIR / "test_metadata.parquet"

# Raw CSV Files (For reference or auxiliary data)
ARTICLES_CSV_PATH = INPUT_DIR / "articles.csv"
CUSTOMERS_CSV_PATH = INPUT_DIR / "customers.csv"
SAMPLE_SUBMISSION_CSV_PATH = INPUT_DIR / "sample_submission.csv"

# ==========================================
# GLOBAL HYPERPARAMETERS
# ==========================================
SEED = 42
N_CPUS = 12  # Available vCPUs

# ==========================================
# STAGE 1: RETRIEVAL CONFIGURATION
# ==========================================
# Number of candidates to retrieve per user for the ranking stage
TOP_K_RETRIEVAL = 100

# Decay parameters for time-weighting interactions
# Using power-law decay: w = 1 / (1 + days) ** EXPONENT
# Cite solution_lesson_node_00011
TIME_DECAY_EXPONENT = 2.0

# Limit for user history items (Importance-Based Truncation)
# Cite solution_lesson_node_00012
HISTORY_ITEM_LIMIT = 30

# Weight for the user's own history in the final score calculation
# Score = (User_History @ Transition_Matrix) + (ALPHA * User_History)
# Cite solution_lesson_node_00011
HISTORY_WEIGHT_ALPHA = 1.5

# ==========================================
# STAGE 2: RANKING CONFIGURATION
# ==========================================
# Number of final predictions to submit per user
TOP_K_SUBMISSION = 12

# Visual Feature Extraction
IMAGE_MODEL_NAME = "resnet18"  # Lightweight CNN for embedding extraction
IMAGE_EMBEDDING_DIM = 512  # Output dimension for resnet18 (before classification head)
IMAGE_SIZE = (224, 224)
IMAGE_BATCH_SIZE = 64

# LightGBM Model Parameters
# Optimized for ranking task (lambdarank)
LGBM_PARAMS = {
    "objective": "lambdarank",
    "metric": "ndcg",
    "eval_at": [12],
    "boosting_type": "gbdt",
    "n_estimators": 1000,
    "learning_rate": 0.05,
    "num_leaves": 31,
    "max_depth": -1,
    "min_data_in_leaf": 20,
    "feature_fraction": 0.8,
    "bagging_fraction": 0.8,
    "bagging_freq": 5,
    "verbosity": -1,
    "random_state": SEED,
    "n_jobs": N_CPUS,
    "early_stopping_rounds": 50,
}

# ==========================================
# CACHE FILE PATHS
# ==========================================
# Paths for caching intermediate artifacts to speed up iterative development
CACHE_TRANSITION_MATRIX = WORKING_DIR / "transition_matrix.npz"
CACHE_ARTICLE_EMBEDDINGS = WORKING_DIR / "article_embeddings.npy"
CACHE_ARTICLE_MAP = WORKING_DIR / "article_map.pkl"
CACHE_USER_FEATURES = WORKING_DIR / "user_features.parquet"
CACHE_ITEM_FEATURES = WORKING_DIR / "item_features.parquet"
CACHE_RANKER_TRAIN = WORKING_DIR / "ranker_train_set.parquet"
CACHE_RANKER_VAL = WORKING_DIR / "ranker_val_set.parquet"
